    {
      "fact": "广播站断电原因",
      "before": "未知",
      "after": "旧电源接头雨水倒灌导致进水氧化"
    },
    {
      "fact": "广播站设备状态",
      "before": "彻底断电",
      "after": "初步接通，指示灯亮起，但待绝缘验收"
    }
  ],
  "relationship_delta": [
